def int_to_mini_roman(number):
    """
    Given a positive integer, obtain its roman numeral equivalent as a string,
    and return it in lowercase.
    Restrictions: 1 <= num <= 1000

    Examples:
    >>> int_to_mini_roman(19) == 'xix'
    >>> int_to_mini_roman(152) == 'clii'
    >>> int_to_mini_roman(426) == 'cdxxvi'
    """
    roman_numerals = {
        1: 'i', 4: 'iv', 5: 'v',
        9: 'ix', 10: 'x', 40: 'xl',
        50: 'l', 90: 'xc', 100: 'c', 400: 'cd',
        500: 'd', 900: 'cm', 1000: 'm'
    }

    result = ''
    for num in range(1, number + 1):
        if num == 1:
            result += roman_numerals[1]
        elif num == 4:
            result += roman_numerals[4]
        elif num == 5:
            result += roman_numerals[5]
        elif num == 9:
            result += roman_numerals[9]
        elif num == 10:
            result += roman_numerals[10]
        elif num == 40:
            result += roman_numerals[40]
        elif num == 50:
            result += roman_numerals[50]
        elif num == 90:
            result += roman_numerals[90]
        elif num == 100:
            result += roman_numerals[100]
        elif num == 400:
            result += roman_numerals[400]
        elif num == 500:
            result += roman_numerals[500]
        elif num == 900:
            result += roman_numerals[900]
        elif num == 1000:
            result += roman_numerals[1000]

    return result.lower()
